Template.Markup:
{% comment %}
USAGE: Create a new article, use this as the article template. 
For each group, update priority, scan frequency, add pages, and add entire object type collections.

Pages will only be added once per sitemap.
{% endcomment -%}
{%- set_content_type "application/xml" -%}
<?xml version="1.0" encoding="UTF-8"?>
{%-if entity.is_index.checked -%}
  <sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  {%- for smap in entity.sitemaps -%}
    <sitemap>
      <loc>{{ smap.full_url }}</loc>
      <lastmod></lastmod>
    </sitemap>
  {%- endfor -%}
    </sitemapindex>
{%- else -%}
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  {%- entities var all_entities = has_url:true limit: 9999 include_in_search:true -%}
  {%- var added_entities = null -%}
  {%- comment -%}
  ------------------------------------
  GROUPS
  ------------------------------------
  {%-endcomment-%}
  {%- for num in (1..5) -%}
    {%-var _pages = "pages_" | append: num-%}
    {%-var _freq = "change_frequency_" | append: num-%}
    {%-var _priority = "priority_" | append: num-%}
    {%-var _all = "apply_all_" | append: num-%}
    {%- if entity[_pages] is_valid -%}
      {%- for obj in entity[_pages].items  -%}
        {%- var robots = obj.meta_robots.value | downcase -%}
        {%- unless added_entities contains obj.guid or robots contains "noindex"  -%}
          {%- set added_entities = added_entities | concat: obj.guid -%}
          <url>
            <loc>{{ obj.full_url }}</loc>
            <changefreq>{{ entity[_freq].value }}</changefreq>
            <priority>{{ entity[_priority].value }}</priority>
          </url>
        {%- endunless -%}
      {%-endfor-%}
      {%- endif -%}
      {%- if entity[_all] is_valid -%}
        {%- for obj_type in entity[_all].values -%}
          {%- for obj in all_entities -%}
            {%- var robots = obj.meta_robots.value | downcase -%}
            {%- unless added_entities contains obj.guid or obj_type != obj.object_type  or robots contains "noindex"  -%}
              {%- set added_entities = added_entities | concat: obj.guid -%}
              <url>
                <loc>{{ obj.full_url }}</loc>
                <changefreq>{{ entity[_freq].value }}</changefreq>
                <priority>{{ entity[_priority].value }}</priority>
              </url>
            {%- endunless -%}
          {%- endfor -%}
        {%-endfor-%}
      {%-endif-%}
    {%- endfor -%}
    {%- comment -%}
    ------------------------------------
    ADD ALL REMAINING PAGES
    ------------------------------------
    {%-endcomment-%}
    {%- unless entity.add_only_selected_items.checked -%}
        {%- for obj in all_entities -%}
            {%- var robots = obj.meta_robots.value | downcase -%}
            {%- unless added_entities contains obj.guid or entity.do_not_add_types.values contains obj.object_type or robots contains "noindex" -%}
                {%- set added_entities = added_entities | concat: obj.guid -%}
                <url>
                 <loc>{{ obj.full_url }}</loc>
                 <changefreq>yearly</changefreq>
                 <priority>0.2</priority>
                </url>
            {%- endunless -%}
        {%- endfor -%}
    {%-endunless-%}
    </urlset>
{%- endif %}

