{% include "/partials/_thank_you_main.liquid" %}
{% include "/_footer.liquid" %}

{%- if entity.thank_you_eyebrow.is_valid or entity.thank_you_title.is_valid or entity.thank_you_description.is_valid or entity.thank_you_button_text.is_valid -%}
<section class="thank-you-02 bg-white py-5">
  <div class="container py-2">
    <div class="row g-0 border rounded-4 overflow-hidden shadow-sm">
      <div class="col-12 col-lg-5 bg-primary text-white p-4 p-lg-5 d-flex flex-column justify-content-between">
        <div>
          <div class="thank-you-02-icon d-inline-flex align-items-center justify-content-center border border-white border-opacity-25 rounded-circle flex-shrink-0 mb-4">
            <i class="bi bi-envelope-check fs-2" aria-hidden="true"></i>
          </div>
          <p class="small text-white-50 fw-bold text-uppercase mb-2">Submission complete</p>
          <h2 class="h3 fw-bold mb-0">Your message is in good hands.</h2>
        </div>
        <p class="small text-white-50 mt-5 mb-0">Thank you for taking the time to get in touch.</p>
      </div>

      <div class="col-12 col-lg-7 p-4 p-lg-5">
        {%- if entity.thank_you_eyebrow.is_valid -%}
        <p class="small text-primary fw-bold text-uppercase mb-3">{{ entity.thank_you_eyebrow }}</p>
        {%- endif -%}
        {%- if entity.thank_you_title.is_valid -%}
        <h1 class="display-6 fw-bold text-dark mb-3">{{ entity.thank_you_title }}</h1>
        {%- endif -%}
        {%- if entity.thank_you_description.is_valid -%}
        <p class="lead text-secondary mb-4">{{ entity.thank_you_description }}</p>
        {%- endif -%}

        <div class="border-top pt-4 mt-4">
          <h2 class="h6 fw-bold text-dark mb-3">What happens next</h2>
          <ol class="list-unstyled d-grid gap-3 mb-4">
            <li class="d-flex align-items-start gap-3"><span class="badge rounded-pill text-bg-light text-primary">1</span><span class="text-secondary">Our team reviews the details you shared.</span></li>
            <li class="d-flex align-items-start gap-3"><span class="badge rounded-pill text-bg-light text-primary">2</span><span class="text-secondary">We’ll follow up using the contact information you provided.</span></li>
            <li class="d-flex align-items-start gap-3"><span class="badge rounded-pill text-bg-light text-primary">3</span><span class="text-secondary">Together, we’ll work out a helpful next step.</span></li>
          </ol>
          {%- if entity.thank_you_button_text.is_valid and entity.thank_you_button_link.is_valid -%}
          <a class="btn btn-outline-primary" href="{{ entity.thank_you_button_link.value | escape }}">{{ entity.thank_you_button_text }} <i class="bi bi-arrow-right ms-2" aria-hidden="true"></i></a>
          {%- endif -%}
        </div>
      </div>
    </div>
  </div>
</section>
{%- add_stylesheet inline -%}
.thank-you-02-icon {
  width: 5rem;
  height: 5rem;
  flex: 0 0 5rem;
}
{% end_stylesheet %}
{%- endif -%}

{%- if entity.testimonials_section_title.is_valid or entity.testimonials_intro_text.is_valid or entity.testimonials_section_items.is_valid or entity.testimonials_03_image.is_valid -%}
<section class="testimonials-03 bg-white py-5">
  <div class="container py-2">
    <div class="row g-5 align-items-center">
      <div class="col-12 {% if entity.testimonials_03_image.is_valid %}col-lg-6{% endif %}">
        {%- if entity.testimonials_section_title.is_valid -%}
        <h2 class="display-6 fw-normal text-dark mb-3">{{ entity.testimonials_section_title }}</h2>
        {%- endif -%}
        {%- if entity.testimonials_intro_text.is_valid -%}
        <h3 class="h4 fw-normal text-primary mb-4">{{ entity.testimonials_intro_text }}</h3>
        {%- endif -%}

        {%- if entity.testimonials_section_items.is_valid -%}
        <div class="d-grid gap-4">
          {%- for testimonial in entity.testimonials_section_items -%}
          <figure class="mb-0">
            {%- if testimonial.testimonial_text.is_valid -%}
            <blockquote class="mb-2 text-secondary lh-lg">{{ testimonial.testimonial_text }}</blockquote>
            {%- endif -%}
            {%- if testimonial.title.is_valid -%}
            <figcaption class="fw-bold text-dark">— {{ testimonial.title }}</figcaption>
            {%- endif -%}
            {%- if testimonial.testimonial_highlight.is_valid -%}
            <div class="small text-secondary mt-1">{{ testimonial.testimonial_highlight }}</div>
            {%- endif -%}
          </figure>
          {%- endfor -%}
        </div>
        {%- endif -%}
      </div>

      {%- if entity.testimonials_03_image.is_valid -%}
      <div class="col-12 col-lg-6">
        <div class="ratio ratio-1x1 overflow-hidden rounded-3">
          {%- img entity.testimonials_03_image preset:"800x600-crop" class:"w-100 h-100 object-fit-cover" alt:entity.testimonials_03_image.alt|default:'Client project' link:false loading:"lazy" -%}
        </div>
      </div>
      {%- endif -%}
    </div>
  </div>
</section>
{%- endif -%}

{%- if entity.content_04_title.is_valid or entity.content_04_body.is_valid or entity.content_04_image.is_valid -%}
<section class="content-04 bg-light py-5">
  <div class="container py-2">
    <div class="row g-5 align-items-start">
      <div class="col-12 {% if entity.content_04_image.is_valid %}col-lg-6{% else %}col-lg-10 mx-auto{% endif %} {% if entity.content_04_image_position.is_valid and entity.content_04_image_position.value == 'left' %}order-2{% else %}order-1{% endif %}">
        {%- if entity.content_04_title.is_valid -%}
        <h2 class="h2 mb-3 fs-1">{{ entity.content_04_title }}</h2>
        {%- endif -%}
        {%- if entity.content_04_body.is_valid -%}
        <div class="text-body">{{ entity.content_04_body }}</div>
        {%- endif -%}
      </div>

      {%- if entity.content_04_image.is_valid -%}
      <div class="col-12 col-lg-6 {% if entity.content_04_image_position.is_valid and entity.content_04_image_position.value == 'left' %}order-1{% else %}order-2{% endif %}">
        <div class="ratio ratio-1x1 overflow-hidden">
          {%- img entity.content_04_image preset:"800x600-crop" class:"w-100 h-100 object-fit-cover" alt:entity.content_04_image.alt|default:'' link:false loading:"lazy" -%}
        </div>
      </div>
      {%- endif -%}
    </div>
  </div>
</section>
{%- endif -%}

{%- if entity.banner_05_title.is_valid or entity.banner_05_description.is_valid or entity.banner_05_background_image.is_valid -%}
<section class="banner-05 py-5 bg-white">
  <div class="container py-2">
    <div class="banner-05-frame position-relative overflow-hidden bg-dark d-flex align-items-center justify-content-center text-center">
      {%- if entity.banner_05_background_image.is_valid -%}
      {%- img entity.banner_05_background_image preset:"1920x600-crop" class:"position-absolute top-0 start-0 w-100 h-100 object-fit-cover" alt:"" link:false loading:"eager" -%}
      {%- endif -%}
      <div class="position-absolute top-0 start-0 w-100 h-100 bg-dark opacity-50" aria-hidden="true"></div>
      <div class="position-relative w-100 px-3 py-5">
        <div class="row justify-content-center">
          <div class="col-12 col-lg-10">
            {%- if entity.banner_05_title.is_valid -%}
            <h1 class="display-5 fw-semibold text-white mb-3">{{ entity.banner_05_title }}</h1>
            {%- endif -%}
            {%- if entity.banner_05_description.is_valid -%}
            <p class="lead text-white mb-0">{{ entity.banner_05_description }}</p>
            {%- endif -%}
          </div>
        </div>
      </div>
    </div>
  </div>
</section>
{%- add_stylesheet inline -%}
.banner-05-frame {
  min-height: 29.5rem;
}

@media (max-width: 767.98px) {
  .banner-05-frame {
    min-height: 23rem;
  }
}
{% end_stylesheet %}
{%- endif -%}

{%- if entity.content_06_eyebrow.is_valid or entity.content_06_title.is_valid or entity.content_06_bullets.is_valid or entity.content_06_closing_text.is_valid or entity.content_06_image.is_valid -%}
<section class="content-06 bg-light py-5">
  <div class="container py-2">
    <div class="row g-5 align-items-start">
      <div class="col-12 col-lg-6">
        {%- if entity.content_06_eyebrow.is_valid -%}
        <p class="h5 mb-0 fw-bolder">{{ entity.content_06_eyebrow }}</p>
        {%- endif -%}
        {%- if entity.content_06_title.is_valid -%}
        <h2 class="fs-2 fw-bold text-primary mb-4">{{ entity.content_06_title }}</h2>
        {%- endif -%}
        {%- if entity.content_06_bullets.is_valid -%}
        <ul class="list-unstyled d-grid gap-2 mb-0">
          {%- for item in entity.content_06_bullets -%}
            {%- if item.text.is_valid -%}
            <li class="d-flex align-items-start gap-2">
              <i class="bi bi-arrow-right-circle-fill fs-5 text-dark flex-shrink-0 align-self-start" aria-hidden="true"></i>
              <span class="h5 align-self-start">{{ item.text }}</span>
            </li>
            {%- endif -%}
          {%- endfor -%}
        </ul>
        {%- endif -%}
        {%- if entity.content_06_closing_text.is_valid -%}
        <p class="fs-3 fst-italic text-dark mt-4 mb-0">{{ entity.content_06_closing_text | newline_to_br }}</p>
        {%- endif -%}
      </div>

      {%- if entity.content_06_image.is_valid -%}
      <div class="col-12 col-lg-6">
        {%- img entity.content_06_image class:"img-fluid w-100" alt:entity.content_06_image.alt|default:'' link:false loading:"lazy" -%}
      </div>
      {%- endif -%}
    </div>
  </div>
</section>
{%- endif -%}

{%- if entity.content_05_items.is_valid -%}
<section class="content-05 bg-white py-5">
  <div class="container py-2">
    <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-4">
      {%- for item in entity.content_05_items -%}
      <div class="col">
        <article class="h-100">
          {%- if item.image.is_valid -%}
          <div class="ratio ratio-1x1 overflow-hidden">
            {%- img item.image preset:"800x600-crop" class:"w-100 h-100 object-fit-cover" alt:item.image.alt|default:'' link:false loading:"lazy" -%}
          </div>
          {%- endif -%}
          {%- if item.title.is_valid -%}
          <h2 class="h4 fw-semibold mt-3 mb-0">{{ item.title }}</h2>
          {%- endif -%}
        </article>
      </div>
      {%- endfor -%}
    </div>
  </div>
</section>
{%- endif -%}

{%- if entity.banner_05_title.is_valid or entity.banner_05_description.is_valid or entity.banner_05_background_image.is_valid -%}
<section class="banner-05 py-5 bg-white">
  <div class="container py-2">
    <div class="banner-05-frame position-relative overflow-hidden bg-dark d-flex align-items-center justify-content-center text-center">
      {%- if entity.banner_05_background_image.is_valid -%}
      {%- img entity.banner_05_background_image preset:"1920x600-crop" class:"position-absolute top-0 start-0 w-100 h-100 object-fit-cover" alt:"" link:false loading:"eager" -%}
      {%- endif -%}
      <div class="position-absolute top-0 start-0 w-100 h-100 bg-dark opacity-50" aria-hidden="true"></div>
      <div class="position-relative w-100 px-3 py-5">
        <div class="row justify-content-center">
          <div class="col-12 col-lg-10">
            {%- if entity.banner_05_title.is_valid -%}
            <h1 class="display-5 fw-semibold text-white mb-3">{{ entity.banner_05_title }}</h1>
            {%- endif -%}
            {%- if entity.banner_05_description.is_valid -%}
            <p class="lead text-white mb-0">{{ entity.banner_05_description }}</p>
            {%- endif -%}
          </div>
        </div>
      </div>
    </div>
  </div>
</section>
{%- add_stylesheet inline -%}
.banner-05-frame {
  min-height: 29.5rem;
}

@media (max-width: 767.98px) {
  .banner-05-frame {
    min-height: 23rem;
  }
}
{% end_stylesheet %}
{%- endif -%}

{% include "/_header.liquid" %}
{% include "/partials/_banner_background_2.liquid" %}
{% include "/partials/_generic_left_right.liquid" %}
{% include "/partials/_generic_left_right_2.liquid" %}
{% include "/partials/_services_card_grid.liquid" %}
{% include "/partials/_logo_carrucel.liquid" %}
{% include "/partials/_cta_banner.liquid" %}
{% include "/_footer.liquid" %}

{%- if entity.banner_06_title.is_valid or entity.banner_06_description.is_valid or entity.banner_06_background_image.is_valid -%}
<section class="banner-06 position-relative {% if entity.banner_06_height.is_valid %}banner-06--{{ entity.banner_06_height.value | classname }}{% else %}banner-06--standard{% endif %}">
  <div class="banner-06-frame position-relative overflow-hidden bg-dark d-flex align-items-center justify-content-center text-center">
    {%- if entity.banner_06_background_image.is_valid -%}
    {%- img entity.banner_06_background_image preset:"1920x600-crop" class:"position-absolute top-0 start-0 w-100 h-100 object-fit-cover" alt:"" link:false loading:"eager" -%}
    {%- endif -%}
    <div class="position-absolute top-0 start-0 w-100 h-100 bg-dark opacity-50" aria-hidden="true"></div>
    <div class="container position-relative py-5">
      <div class="row justify-content-center">
        <div class="col-12 col-lg-10">
          {%- if entity.banner_06_title.is_valid -%}
          <h1 class="display-5 fw-semibold text-white mb-3">{{ entity.banner_06_title }}</h1>
          {%- endif -%}
          {%- if entity.banner_06_description.is_valid -%}
          <p class="lead text-white mb-0">{{ entity.banner_06_description }}</p>
          {%- endif -%}
        </div>
      </div>
    </div>
  </div>
</section>
{%- add_stylesheet inline -%}
.banner-06-frame {
  height: 42vh;
  min-height: 20rem;
  max-height: 32rem;
}

.banner-06--slim .banner-06-frame {
  height: 30vh;
  min-height: 14rem;
  max-height: 18rem;
}

.banner-06--large .banner-06-frame {
  height: 62vh;
  min-height: 28rem;
  max-height: 42rem;
}

@media (max-width: 767.98px) {
  .banner-06-frame {
    height: 42vh;
    min-height: 18rem;
    max-height: 28rem;
  }

  .banner-06--slim .banner-06-frame {
    height: 32vh;
    min-height: 14rem;
    max-height: 18rem;
  }

  .banner-06--large .banner-06-frame {
    height: 54vh;
    min-height: 23rem;
    max-height: 34rem;
  }
}
{% end_stylesheet %}
{%- endif -%}

{%- if entity.content_06_title.is_valid or entity.content_06_body.is_valid or entity.content_06_image.is_valid -%}
<section class="content-04 bg-light py-5">
  <div class="container py-2">
    <div class="row g-5 align-items-start">
      <div class="col-12 {% if entity.content_06_image.is_valid %}col-lg-6{% else %}col-lg-10 mx-auto{% endif %} {% if entity.content_06_image_position.is_valid and entity.content_06_image_position.value == 'left' %}order-2{% else %}order-1{% endif %}">
        {%- if entity.content_06_title.is_valid -%}
        <h2 class="h2 mb-3 fs-1">{{ entity.content_06_title }}</h2>
        {%- endif -%}
        {%- if entity.content_06_body.is_valid -%}
        <div class="text-body">{{ entity.content_06_body }}</div>
        {%- endif -%}
      </div>

      {%- if entity.content_06_image.is_valid -%}
      <div class="col-12 col-lg-6 {% if entity.content_06_image_position.is_valid and entity.content_06_image_position.value == 'left' %}order-1{% else %}order-2{% endif %}">
        {%- if entity.content_06_image_ratio.is_valid and entity.content_06_image_ratio.value == 'landscape' -%}
        <div class="ratio ratio-4x3 overflow-hidden">
          {%- img entity.content_06_image preset:"800x600-crop" class:"w-100 h-100 object-fit-cover" alt:entity.content_06_image.alt|default:'' link:false loading:"lazy" -%}
        </div>
        {%- elsif entity.content_06_image_ratio.is_valid and entity.content_06_image_ratio.value == 'widescreen' -%}
        <div class="ratio ratio-16x9 overflow-hidden">
          {%- img entity.content_06_image preset:"1920x1080-crop" class:"w-100 h-100 object-fit-cover" alt:entity.content_06_image.alt|default:'' link:false loading:"lazy" -%}
        </div>
        {%- else -%}
        <div class="ratio ratio-1x1 overflow-hidden">
          {%- img entity.content_06_image preset:"300x300-max" class:"w-100 h-100 object-fit-cover" alt:entity.content_06_image.alt|default:'' link:false loading:"lazy" -%}
        </div>
        {%- endif -%}
      </div>
      {%- endif -%}
    </div>
  </div>
</section>
{%- endif -%}

{%- if entity.services_items.is_valid -%}
<section class="services-04 py-5 bg-white">
  <div class="container py-2">
    {%- if entity.services_eyebrow.is_valid or entity.services_title.is_valid or entity.services_description.is_valid -%}
    <div class="row justify-content-center text-center mb-5">
      <div class="col-12 col-lg-9">
        {%- if entity.services_eyebrow.is_valid -%}
        <p class="small text-uppercase text-primary fw-semibold mb-3">{{ entity.services_eyebrow }}</p>
        {%- endif -%}
        {%- if entity.services_title.is_valid -%}
        <h2 class="display-5 fw-bold text-dark mb-3">{{ entity.services_title }}</h2>
        {%- endif -%}
        {%- if entity.services_description.is_valid -%}
        <div class="lead text-secondary">{{ entity.services_description }}</div>
        {%- endif -%}
      </div>
    </div>
    {%- endif -%}

    <div class="row g-0">
      {%- for service in entity.services_items -%}
      {%- assign service_position = forloop.index0 | modulo: 2 -%}
      <div class="col-12">
        <article class="row g-0 align-items-stretch{% if service_position == 1 and service.services_image.is_valid %} flex-lg-row-reverse{% endif %}">
          <div class="col-12 {% if service.services_image.is_valid %}col-lg-6{% endif %}">
            <div class="h-100 d-flex flex-column justify-content-center text-white p-4 p-lg-5 {% if service_position == 1 %}bg-dark{% else %}bg-primary{% endif %}">
              {%- if service.title.is_valid -%}
              <h3 class="display-6 fw-bold mb-3">{{ service.title }}</h3>
              {%- endif -%}
              {%- if service.services_summary.is_valid -%}
              <div class="mb-4">{{ service.services_summary }}</div>
              {%- endif -%}
              {%- if service.has_url -%}
              <a class="btn btn-outline-light align-self-start" href="{{ service.full_url | escape }}">Learn More</a>
              {%- endif -%}
            </div>
          </div>
          {%- if service.services_image.is_valid -%}
          <div class="col-12 col-lg-6">
            <div class="ratio ratio-1x1 overflow-hidden">
              {%- img service.services_image preset:"720x480-crop" class:"w-100 h-100 object-fit-cover" alt:service.services_image.alt|default:service.title link:false loading:"lazy" -%}
            </div>
          </div>
          {%- endif -%}
        </article>
      </div>
      {%- endfor -%}
    </div>
  </div>
</section>
{%- endif -%}

Stylesheet.StyleSheetText:
.fade {
  @include transition($transition-fade);

  &:not(.show) {
    opacity: 0;
  }
}

// scss-docs-start collapse-classes
.collapse {
  &:not(.show) {
    display: none;
  }
}

.collapsing {
  height: 0;
  overflow: hidden;
  @include transition($transition-collapse);

  &.collapse-horizontal {
    width: 0;
    height: auto;
    @include transition($transition-collapse-width);
  }
}
// scss-docs-end collapse-classes

